mockup.css:
.mock-hero-spec-ticker { background: #eef1f2; color: #12181c; font-family: "Inter", ui-sans-serif, sans-serif;
  display: flex; flex-direction: column; justify-content: center; gap: 4cqw; padding: 0 5cqw; }
.mock-hero-spec-ticker h4 { margin: 0; font-size: 7.8cqw; line-height: .98; font-weight: 300; letter-spacing: -.03em; }
.mock-hero-spec-ticker h4 b { font-weight: 700; }
.mock-hero-spec-ticker .ticker { border-block: 1px solid rgba(18,24,28,.22); padding: 2.2cqw 0;
  display: flex; gap: 2.6cqw; align-items: baseline; font-family: ui-monospace, monospace;
  font-size: 1.65cqw; letter-spacing: .06em; text-transform: uppercase; white-space: nowrap; }
.mock-hero-spec-ticker .ticker s { text-decoration: none; opacity: .35; }
